import { citypesearch } from "@/api/system/ciModel";
import modelForm from './components/modelManageComponent/modelFom';
import levelForm from './components/modelManageComponent/levelForm';
import levelManage from './components/modelManageComponent/levelManage';
import modelDetailForm from './modelDetailForm';

export default {
  components: { 
    modelForm,
    levelForm,
    levelManage,
    modelDetailForm,
  },
  data() {
    return{
      showTopo: false,
      modeShowType: "card",
      searchText: '',
      modelList: [],
      pageLoading: false,
      // 弹窗相关
      showModel: false,
      showLevel: false,
      showLevelManage: false,
      showDetail: false,
      ciId: '', //模型id
      showType: '',
    }
  },
  mounted() {
    this.setPageContentHeight()
    this.getModelList()
  },
  methods: {
    // 获得所有模型列表
    getModelList() {
      this.pageLoading = true
      citypesearch().then(res => {
        this.modelList = res.Return
        this.pageLoading = false
      }).catch(err => {
        this.pageLoading = false
      })
    },
    // 设置图标颜色
    getIconClass(row) {
      if (row.isVirtual) {
        return 'text-grey';
      } else {
        if (!row.isAbstract) {
          return 'text_primary';
        } else {
          return 'text_default';
        }
      }
    },
    // 查看模型详情
    seeCiDetail(row) {
      this.$refs.ciDetail.style.width = 'calc(100% - 40px)'
      this.ciId = row.id
      this.showDetail = true

    },
    // 返回模型管理
    backManage() {
      this.$refs.ciDetail.style.width = '0px'
      this.$nextTick(() => {
        this.showDetail = false
      })
    },
    // 层级保存成功回调
    saveCitype() {
      this.showLevel = false
      this.showLevelManage = false
      this.getModelList()
    },
    // 模型保存回调
    saveCi() {
      this.showModel = false
      this.getModelList()
    },
    // 新增模型
    addCi() {
      this.showModel = true
      this.showType = '新增'
    },
    // 编辑模型
    editCi() {
      this.showModel = true
      this.showType = '修改'
    },
  }
}
